  start_journey_hint: 'A standard world with the tutorial',
  hb_metro_title: 'Metro and levels',
  hb_metro_1: 'Railways run on four levels: the surface, a shallow tunnel, a deep tunnel and a viaduct. Pick the level in the Level row of the track, station, depot and signal tools. Urban Railways unlocks the tunnel and viaduct, Deep Tunnelling the deep level.',
  hb_metro_2: 'Levels meet at portals and ramps: a straight track end on one level continues on the next. Tunnels cost more to build and have a monthly upkeep; deep tunnels most.',
  hb_metro_3: 'Underground stations get a street entrance where there is room; the View button on the tool strip shows what lies below the ground.',
  hb_metro_4: 'The map panel draws your metro lines on their own when you choose the metro filter. FIND knows everyday words for all of this: try “subway”, “U-Bahn” or “metro map”.',
  hb_corridors_title: 'Four-track corridors',
  hb_corridors_1: 'Second pair, in the track tool, lays a second double track beside an existing line in one drag, with crossovers between the pairs. Choose the side and what the new pair is for.',
  hb_corridors_2: 'Track role paints tracks as local, express or freight. Trains prefer tracks of their kind and use the others when theirs is missing or blocked, so fast trains overtake slow ones.',
  hb_corridors_3: 'The Track roles overlay shows every role with its own colour and pattern; the legend under the tool strip names them.',
  hb_corridors_4: 'Where two lines must cross without meeting, take one onto a viaduct or into a tunnel: a flyover keeps both running.',
  hb_planning_title: 'Planning and blueprints',
  hb_planning_1: 'Planning mode (J) lets you draw whole projects without building anything: the plan shows what it would cost.',
  hb_planning_2: 'When you are ready, build all of a project, or just the part that still fits. A step that no longer fits is marked so you can change it.',
  hb_planning_3: 'Blueprints are reusable layouts: save part of your network, then place it again, rotated (R) or mirrored (M). The price shown is the price charged.',
  hb_planning_4: 'Blueprints can be exported as text and shared; importing one checks it first and never builds on its own.',
  hb_eras_title: 'Things that show their age',
  hb_eras_1: 'Stations, airports, ports, level crossings, overhead wires, tunnel portals and bus stops keep the look of the year they were built.',
  hb_eras_2: 'Renovation brings the look up to date for a price. It never changes what a place can handle: capacity stays the same.',
  hb_eras_3: 'A station 40 years or older can be listed as heritage: it keeps its look for good. Rival companies renovate rarely, only their important stations, and sometimes keep an old one too.',
  hb_eras_4: 'Snow settles in winter and melts in spring; nights are darker, with lit windows and lamps.',
  hb_complexes_title: 'Station complexes',
  hb_complexes_1: 'Stations and stops a short walk apart form one complex: passengers change between them on foot. The station inspector lists them with the walking time.',
  hb_complexes_2: 'A change of level takes time: 20 seconds per level on the stairs. Where levels meet you can add lifts (12 seconds) or escalators (7 seconds); each costs once and a little upkeep every month.',
  hb_complexes_3: 'Bike parking lets a station reach one tile further into the streets; park & ride draws passengers from towns a few tiles further away.',
  hb_complexes_4: 'Quicker changes make journeys through the complex more attractive, so more passengers choose your network.',
  hb_find_title: 'Finding things',
  hb_find_1: 'FIND (Ctrl+K) looks for towns, stations, stops, industries, vehicles and lines, and for the game\'s commands.',
  hb_find_2: 'It understands everyday English and German words, small typos and missing accents: “money”, “Stau”, “abreissen”, “bahnof”. It only lists: nothing happens until you choose a result.',
  hb_find_3: 'In the vehicle catalogue you can describe what you want, like “fast electric freight loco from the 60s”. The description fills the normal filters, shown as chips; Clear filters resets them. Words it does not know are named.',
  hb_find_4: 'All of this works offline on your device. What you type is never sent anywhere.',
  hb_access_title: 'Seeing and using the game',
  hb_access_1: 'Overlays never rely on colour alone: every class has its own pattern (solid, stripes, dots, outline, checks) and a legend in words under the tool strip.',
  hb_access_2: 'Light signals show stop in the upper lamp and clear in the lower one; semaphore arms point up or level.',
  hb_access_3: 'Escape closes one thing at a time: a question, a menu, a panel, then the tool. It also leaves a text field.',
  hb_access_4: 'Settings offer high contrast, reduced motion, a larger interface and switching off camera motion and screen shake. Errors say what went wrong and what to do next.',
