  ng_terrain_adv: 'Advanced terrain settings',
  ng_terrain_adv_help: 'Every value starts at the preset\'s. A height map replaces the shape of the land; climate, forest, farmland and towns still apply.',
  ng_terrain_reset: 'Reset to the preset',
  ng_regen: 'Try another seed',
  ng_tstats: '{w}% water · {m}% mountains · {f}% forest · {fl}% farmland · {n} towns · {i} industries',
  ng_tcost: 'Between neighbouring towns: {flat}% flat, {slope}% slopes, {bridge}% bridges, {tunnel}% tunnels. Building costs: {c}',
  tcost_low: 'low',
  tcost_medium: 'medium',
  tcost_high: 'high',
  ng_mega_warn: '192 × 192 is the largest map: about nine times the classic one. Building the world takes a moment, and older phones may run slower. The game saves as usual.',
  terrain_classic: 'Classic',
  terrain_classic_desc: 'The familiar Tracklands world: meadows in the middle, a west coast, two rivers, mountains in the north and south.',
  terrain_countryside: 'Gentle countryside',
  terrain_countryside_desc: 'Soft hills, three rivers, farmland around the towns and hardly a mountain. Cheap to build: a good first game.',
  terrain_plains: 'Great plains',
  terrain_plains_desc: 'Flat, open and dry, with wide fields and many small towns. Long straight lines; freight and farm goods rule.',
  terrain_highlands: 'Highlands',
  terrain_highlands_desc: 'Rolling high ground and wooded hills. Rivers cut valleys and low passes link the regions; lines follow the valleys.',
  terrain_alpine: 'Alpine',
  terrain_alpine_desc: 'High mountains, deep valleys and few towns. Tunnels and bridges are expensive; a good valley line is worth a lot.',
  terrain_riverlands: 'Riverlands',
  terrain_riverlands_desc: 'Five wide rivers and their valleys. Towns sit by the water; ships are useful, rail needs bridges.',
  terrain_lakes: 'Lake country',
  terrain_lakes_desc: 'Many lakes between woods and meadows. Lines wind around the water; ferries can take the short way.',
  terrain_coastal: 'Coastal',
  terrain_coastal_desc: 'A long coast in the west and south with harbour towns. Ports and coastal shipping pay; rail links the hinterland.',
  terrain_archipelago: 'Archipelago',
  terrain_archipelago_desc: 'Every region is an island, the start island included. Ships and long bridges connect them; expansion costs more.',
  terrain_industrial: 'Industrial basin',
  terrain_industrial_desc: 'Low, open land with half again as many industries and more towns. Busy freight networks and short hauls.',
  terrain_frontier: 'Dry frontier',
  terrain_frontier_desc: 'Dry plains, mesas and scattered towns. Little water and forest; mines and oil wells lie on their seams.',
  terrain_snowland: 'Northern snowland',
  terrain_snowland_desc: 'A cold world of pine forests, snowfields and frozen hills. Snow is more common; timber and mining carry the economy.',
  terrain_continental: 'Continental (mega)',
  terrain_continental_desc: 'A whole continent with seas all round, five rivers, passes through the mountains and more of everything. Made for 192 × 192.',
