  haptics: 'Vibration on phones (build, long press)',
  hb_roads_title: 'Roads, bridges and tunnels',
  hb_roads_1: 'The road tool builds eight road types: pick one in the bar. Each has a speed limit and a capacity (how many cars before it slows).',
  hb_roads_2: 'Drag across a river (up to 8 tiles) for a bridge. Drag straight through a hill (up to 12 tiles) for a tunnel.',
  hb_roads_3: 'Four-lane roads, expressways and highways cross railways on an overpass instead of a level crossing, so trains never wait for them.',
  hb_roads_4: 'One-way streets are driven only in the direction you drew them. Busways carry buses and coaches only.',
  hb_roads_5: 'Drawing a better type over an existing road upgrades it for the difference in price. Undo restores the old type.',
  hb_terminals_title: 'Ports and airports',
  hb_terminals_1: 'Ports and airports come in three sizes. Expand them from their inspector: more reach, faster handling, the biggest ships and aircraft.',
  hb_terminals_2: 'A port has berths: ships beyond them wait off the quay. An airport has runway slots: aircraft wait at the gate or circle.',
  hb_terminals_3: 'The inspector shows berths in use and runway slots used last month. Waiting ships or circling aircraft mean: expand or spread the traffic.',
  hb_terminals_4: 'Ships are serviced at a port with cranes, aircraft at any airport, while they load.',
  hb_standing_title: 'Reputation, contracts and rivals',
  hb_standing_1: 'Your reputation comes from how the towns you serve rate you, how good your lines are and your contract record. It scales contract rewards.',
  hb_standing_2: 'Some contracts have deadlines: letting them lapse hurts your record and the town. Service-level contracts count whole months at a quality.',
  hb_standing_3: 'A town that likes you may offer a concession: run good local transit for three months and rival buses stay out for a year.',
  hb_standing_4: 'Rivals run coaches, town buses or trucks and pay their own way. One in debt for three months sells cheaply; from level 8 you can buy any rival.',
  hb_standing_5: 'The finance panel\'s ANALYSIS tab shows profit by division, line, town and cargo, cash flow and what each vehicle has paid back.',
  hb_fleetcare_title: 'Fleet care',
  hb_fleetcare_1: 'Park an old vehicle in a depot or garage and refurbish it: most of its age comes off for about a third of the new price.',
  hb_fleetcare_2: 'Vehicles 12 years or older can run heritage services: leisure and tourist trips pay much more, and towns draw more tourists.',
  hb_fleetcare_3: 'Trains service at depots and buses at garages when due; trams at their line\'s first stop, ships at a port with cranes, aircraft at airports.',
  hb_fleetcare_4: 'Replacement rules swap old models for newer ones while they are serviced.',
  hb_saves_title: 'Saves and backups',
  hb_saves_1: 'The game saves itself (Settings: how often). Backups are kept every 5 minutes of play, on leaving to the title and before an import.',
  hb_saves_2: 'Settings → Backups lists them; restore any, the current game is backed up first. After an error the game keeps a crash snapshot too.',
  hb_saves_3: '“Check this game” looks for things that should never happen and changes nothing. Copy the diagnostics for a bug report; they contain no personal data.',
  hb_saves_4: 'Export a save as text or a file to move it to another device; everything else stays on this one.',
  hb_shortcuts_title: 'Keyboard shortcuts',
  hb_shortcuts_1: 'Space: pause · . and , : faster / slower (up to 8×)',
  hb_shortcuts_2: 'F or Ctrl+K: find anything, or type a command (open a panel, pick a tool, show an overlay)',
  hb_shortcuts_3: '1 select · 2 track · 3 station · 4 depot · 5 train shop · 6 bulldoze · 7 decorate · 8 signal · 9 waypoint',
  hb_shortcuts_4: 'R road · B stop · L line · I industry · O overlays · H traffic heat map',
  hb_shortcuts_5: 'T trains · M map · ? handbook · Esc close or cancel · Enter build (touch plan)',
  hb_shortcuts_6: 'W A S D or arrows: move the camera · Q / E: rotate · + / −: zoom (with the station tool: tracks)',
  hb_shortcuts_7: 'Ctrl+Z: undo the last construction (10 seconds)',
  hb_shortcuts_8: 'In the cab: W / S power, X brake, Esc leaves',
