  purpose_business: 'Business',
  purpose_intercity: 'Intercity',
  purpose_commute_desc: 'To jobs: offices, factories, shops. Short trips, willing to travel a little.',
  purpose_shopping_desc: 'To shops and markets. Only short trips.',
  purpose_education_desc: 'To universities and civic buildings.',
  purpose_leisure_desc: 'To parks, stadiums, museums and landmarks.',
  purpose_tourism_desc: 'To tourist towns, hotels and landmarks. Long trips are fine; pays more.',
  purpose_business_desc: 'To offices and convention centres of big towns. Pays the most.',
  purpose_intercity_desc: 'Between towns far apart, to their people. Long trips.',
  hb_journeys_title: 'Journeys & transfers',
  hb_journeys_1: 'Every load remembers its journey: where it started, when, where it is heading and which vehicles carried it.',
  hb_journeys_2: 'Travellers make trips with a purpose – commuting, shopping, education, leisure, tourism, business, intercity – to what other places offer, if the trip is quick enough.',
  hb_journeys_3: 'They choose the best way through all your lines: bus, tram, train, ferry and aircraft, walking between stops close together. Waiting, riding and every change count.',
  hb_journeys_4: 'Freight finds its own way to a place that takes it: a lorry can bring coal to a freight station where a train takes it on. No need to route each load yourself.',
  hb_journeys_5: 'A journey is paid once, on arrival: the fare for the whole distance is shared by every vehicle that carried it, by the distance each drove. Changing vehicles earns nothing by itself.',
  hb_journeys_6: 'Trains without a timetable (automatic) still take anyone waiting for “any train”; give trains a route to make them part of the network.',
  size_192: 'Mega',
  size_192_desc: '192 × 192 tiles: a whole country, over a hundred towns; for fast devices',
  airport_size_1: 'Regional airport',
  airport_size_2: 'International airport',
  airport_stats: 'Reach {r} tiles · turnaround {t} %',
  airport_upgrade: 'Expand to international',
  airport_international_desc: 'Longer runway and a bigger terminal: reaches further, turns aircraft 30 % faster, takes the Cargojet and the Skyliner 300.',
  airport_upgraded: '{name} is now an international airport',
  airport_international: 'International airport',
  err_airport_small: 'This aircraft needs an international airport at every stop',
  hb_rollingstock_title: 'Locomotives & units',
  hb_rollingstock_1: 'Every era offers several locomotives for different jobs: shunters and local engines are cheap, intercity and express engines are fast, heavy-freight and mountain engines pull more up hills. Later models are not better at everything.',
  hb_rollingstock_2: 'Multiple units (DMU, EMU, high-speed unit) carry passengers in their power cars, drive from either end, board faster and keep their acceleration when full. They run as a set with unit cars and never haul freight wagons.',
  hb_rollingstock_3: 'Passenger composition pays a little extra: a premium coach raises fares, a dining car adds to every fare of the train, sleeping cars pay more on long journeys. Mail vans and parcel vans take the post along.',
  hb_rollingstock_4: 'Specialised wagons carry more of one cargo (grain, cement, coils, chemicals) or much more of many (high-capacity wagons need Heavy Haul). Double-stack container cars are too tall for overhead wires: pull them with steam or diesel.',
  hb_rollingstock_5: 'The vehicle catalogue (menu: Vehicles) lists every model with its role, stats, unlock, strengths and weaknesses. Search and filter it, star favourites (they come first in the builders) and compare up to four models side by side.',
