  mu_badge_desc: 'Carries passengers itself, drives from either end, boards fast and keeps its acceleration when full.',
  special_badge: 'Specialised freight',
  hb_freight_5: 'Newer chains: stone and sand make cement, clay makes bricks — building materials that let towns grow faster. Livestock, milk, fruit and fish become food; oil makes chemicals; steel, chemicals and machinery make vehicles; copper and chemicals make electronics. Power stations burn coal and oil.',
  hb_freight_6: 'Any vehicle that fits can carry any cargo, but some modes pay better: bulk goods by rail and ship, perishables by lorry, valuable goods by lorry and plane. The industry panel shows what pays best.',
