  town_materials: 'Building materials this month: {n} (faster growth)',
  news_town_landmark: '{town} opens its new {what}',
  hb_cities_title: 'Cities and their character',
  hb_cities_1: 'Every town has a character: historic, industrial, commuter, tourist, port, university, tech, market, mountain or railway town. You see it in the town panel.',
  hb_cities_2: 'The character shapes the streets (grid, rings around an old centre, a long street along a coast or valley), the buildings and their colours, and how tall the town may build.',
  hb_cities_3: 'It also changes what the town wants: university and commuter towns travel a lot, tourist towns most in summer, industrial towns need more goods and machinery to grow, market towns less food.',
  hb_cities_4: 'Towns raise landmarks as they grow: a cathedral, a museum, a stadium, a lighthouse … Some are protected and can never be demolished; the others need the council\'s heritage approval.',
  hb_cities_5: 'Big cities grow a second centre of high buildings, redevelop low houses into flats and offices, and neighbouring cities form one urban area with more travel between them.',
  arch_historic: 'Historic city',
  arch_historic_desc: 'A dense old centre with ring streets and old architecture. The council guards its heritage; land in the centre is dear.',
  arch_industrial: 'Industrial city',
  arch_industrial_desc: 'Works and warehouses on the outskirts, brick streets, wide blocks. Asks for goods, machinery and steel.',
  arch_commuter: 'Commuter town',
  arch_commuter_desc: 'Wide suburbs around a compact centre; many people travel, and the railway pulls the town towards its stations.',
  arch_tourism: 'Tourist town',
  arch_tourism_desc: 'Hotels, museums and squares. Visitors come most in summer and least in winter.',
  arch_port: 'Port city',
  arch_port_desc: 'A long waterfront with harbour sheds; it grows along the coast and asks for fuel and goods.',
  arch_university: 'University town',
  arch_university_desc: 'A campus and plenty of students: many travellers and much mail.',
  arch_tech: 'Tech city',
  arch_tech_desc: 'Glass towers and offices: tall, valuable and full of mail.',
  arch_market: 'Market town',
  arch_market_desc: 'A small centre among farms; grows slowly, needs little food from elsewhere, land is cheap.',
  arch_mountain: 'Mountain town',
  arch_mountain_desc: 'Chalets along a valley; the terrain holds it in, so it stays compact. Tunnels are worth it here.',
  arch_railway: 'Railway town',
  arch_railway_desc: 'Grew around the railway: stations draw the town around them more than anywhere else.',
  fam_traditional: 'Traditional architecture',
  fam_brick: 'Industrial brick',
