  town_industries: 'Industry nearby',
  town_relationship: 'Relationship',
  hb_buslines_6: 'Towns have their own cars. Buses and trucks wait at junctions and red lights and slow down on busy streets. A bus lane (road tool, after the Bus Lanes research; cities must approve it) lets buses pass the traffic, and Bus Priority turns the lights green for them sooner.',
  road_mode_lane: 'Bus lane',
  hint_lane: 'Drag along a street: buses and coaches in a bus lane pass the town\'s cars and are not slowed by traffic.',
  hint_drag_lane: 'Drag along an existing street to paint a bus lane',
  err_lane_needs_road: 'Bus lanes go on existing roads and streets',
  err_lane_research: 'Research Bus Lanes first (Cities)',
  err_lane_permit: 'The city council does not approve a bus lane here yet',
  err_lane_permit_town: '{town} does not approve bus lanes yet: its rating of you must reach {n}.',
  lane_built: 'Bus lane painted on {n} tiles',
  lane_len: 'Bus lane: {n} tiles',
  lane_locked: 'Research Bus Lanes (Cities) to paint bus lanes',
  fin_n_lane: 'Bus lane, {n} tiles',
  permit_bus_lane: 'Bus lane in the city',
  res_bus_lanes: 'Bus Lanes',
  res_bus_lanes_desc: 'Paint bus lanes on streets (road tool): buses pass the traffic',
  res_bus_priority: 'Bus Priority',
  res_bus_priority_desc: 'Traffic lights turn green sooner for a waiting bus',
  stop_actions: 'Stop actions',
  vehicle_actions: 'Vehicle actions',
  town_actions: 'Town actions',
  rv_replace: 'Replace',
  rv_replace_with: 'Replace: {name}',
  rv_replaced: '{name} is now a {m}',
  tm_transport: 'Transport',
  tm_districts: 'Districts',
  tm_authority: 'Authority',
  tm_coverage: 'Within walking distance of a stop',
  tm_town_none: 'No public transport yet: build a bus stop or a station here.',
  tm_town_gap: 'The {area} district ({n} % of the town) has no stop in reach.',
  hb_buslines_title: 'Bus lines and stops',
  hb_buslines_1: 'The Lines tool (L) plans a line: tap or click the stops in order, pick a pattern (loop, out and back, one way, shuttle) and a bus model, then Create. The estimate shows trip time, frequency and a sensible number of buses.',
  hb_buslines_2: 'Travellers choose where they want to go. Frequent service makes them wait less; a line with too few buses gets crowded, one with too many runs empty. Automatic allocation buys and sells buses to match demand.',
  hb_buslines_3: 'Upgrade a busy stop: urban stop, bus bay, bus station, terminal, interchange. Bigger stops serve more buses at once, board faster, reach further and make changing to trains easier. Extras like shelters or a transfer hall add comfort and capacity.',
  hb_buslines_4: 'A stop near a railway station feeds it: travellers ride the bus to the train and arriving train passengers take the bus for the last mile.',
  hb_buslines_5: 'Buses age and lose reliability. A garage services them, stores them and sells new ones; a replacement rule renews a model automatically when its buses get old.',
  hb_overview_title: 'Transport panel and advisor',
  hb_overview_1: 'The Transport panel shows every mode in one place: vehicles, lines, money and passengers or cargo for rail, bus, tram, truck, ship and air.',
  hb_overview_2: 'Services lists every line with frequency, passengers, cargo, profit, delay and capacity. Vehicles lists everything you own; filter by type, line, town or status and pick several to act on them together.',
  hb_overview_3: 'Problems collects what the advisor found: crowded or empty lines, full stations and stops, congestion, vehicles without a route, towns without public transport. Many findings come with a button that fixes them.',
  hb_overview_4: 'The advisor never interrupts you. Urgent findings only show as a number on the Transport button.',
