  controls: 'Controls',
  setting_instant_build: 'Instant build (no confirmation on touch)',
  setting_keep_tool: 'Keep the tool after building',
  hb_tycoon_title: 'Running the company',
  hb_tycoon_1: 'Every coin is booked in the finance panel: income and costs by category, per train, station and vehicle, month by month. Tap a log line to see its object.',
  hb_tycoon_2: 'A loan gives cash now for monthly interest. Company value is cash minus debt plus trains, track, stations, industry stakes and recent earnings.',
  hb_tycoon_3: 'Each town rates the company. Good service raises it; demolition, clearing trees and noise lower it. Some permits need a good rating.',
  hb_tycoon_4: 'Buy stakes in industries for monthly dividends; 50 % or more runs the site (+10 % output). Fund expansions or new sites with the industry tool.',
  hb_tycoon_5: 'Rival bus companies compete for the towns\' travellers: the station with the better cargo rating gets more. The company panel ranks you against them.',
  hb_transport_title: 'Roads, water and air',
  hb_transport_1: 'Build roads with the road tool and put bus and truck stops on them. Give each vehicle two or more stops; it earns like a train.',
  hb_transport_2: 'Lay tram track along streets (road tool, Tram track), then tram stops. Trams also carry people across their own town.',
  hb_transport_3: 'Docks go on the shore; ships sail between docks on the same water. Ferries carry passengers, coasters and tankers carry goods.',
  hb_transport_4: 'Airports need a flat 3×3 area. Aircraft are fast but costly: long routes between big towns pay best.',
  hb_transport_5: 'A stop, dock or airport within reach of a railway station hands its passengers and goods to the trains, and is paid for its leg.',
  hb_world_title: 'World, news and goals',
  hb_world_1: 'Seasons follow the calendar. Storms, fog and snow slow vehicles; snow settles in winter; farms produce by season. The top-bar chip explains the weather.',
  hb_world_2: 'The newspaper reports what happens: growing towns and industries, market events, the business cycle and rivals. Tap an item to see it.',
  hb_world_3: 'Boom and slump change what every delivery pays by 12 %. Build in a slump, earn in a boom.',
  hb_world_4: 'Lists find any town, industry or station by name. New games can be larger (96 or 128 tiles) or built from your own height map.',
  hb_world_5: 'Scenarios set goals and a deadline; the editor makes your own and shares them as text. Drive a train yourself with Drive in its panel.',
  ov_trackcheck: 'Track check', ov_trackcheck_desc: 'Red: broken links · amber: track ends at an angle · grey: open track ends',
  ng_rivals: 'Rival companies', rivals: 'Competitors', rival_you: 'you', rival_owned: 'A rival company runs this. You cannot change it.', rival_stats: '{b} buses · {s} stops · last month {p} ●', rivals_help: 'Rival bus companies open lines between towns. Their stops share each town\'s travellers with yours by cargo rating: serve towns well to keep them.', err_rival_stop: 'That belongs to a rival company', news_rival_line: '{rival} opens a bus line {a} – {b}',
