  ng_more_rules: 'Weitere Regeln: Verschleiß, Industrien',
  start_journey_hint: 'Eine Standardwelt mit Einführung',
  hb_metro_title: 'U-Bahn und Ebenen',
  hb_metro_1: 'Bahnen fahren auf vier Ebenen: an der Oberfläche, im flachen Tunnel, im tiefen Tunnel und auf einem Viadukt. Die Ebene wählst du in der Zeile Ebene der Werkzeuge für Gleis, Bahnhof, Depot und Signal. Stadtbahn schaltet Tunnel und Viadukt frei, Tiefbau die tiefe Ebene.',
  hb_metro_2: 'Ebenen treffen sich an Portalen und Rampen: Ein gerades Gleisende auf einer Ebene geht auf der nächsten weiter. Tunnel kosten mehr beim Bau und haben monatlichen Unterhalt, tiefe Tunnel am meisten.',
  hb_metro_3: 'Unterirdische Bahnhöfe bekommen einen Straßenzugang, wo Platz ist; die Schaltfläche Ansicht in der Werkzeugleiste zeigt, was unter der Erde liegt.',
  hb_metro_4: 'Die Karte zeigt deine U-Bahn-Linien für sich, wenn du den Metro-Filter wählst. SUCHEN kennt Alltagswörter dafür: probier „U-Bahn“, „subway“ oder „U-Bahn-Karte“.',
  hb_corridors_title: 'Viergleisige Strecken',
  hb_corridors_1: 'Zweites Paar im Gleiswerkzeug legt mit einem Zug einen zweiten zweigleisigen Strang neben eine bestehende Strecke, mit Weichenverbindungen zwischen den Paaren. Wähle die Seite und wofür das neue Paar da ist.',
  hb_corridors_2: 'Gleisrolle markiert Gleise für Nah-, Fern- oder Güterverkehr. Züge bevorzugen Gleise ihrer Art und weichen aus, wenn diese fehlen oder belegt sind, so überholen schnelle Züge langsame.',
  hb_corridors_3: 'Das Overlay Gleisrollen zeigt jede Rolle mit eigener Farbe und eigenem Muster; die Legende unter der Werkzeugleiste benennt sie.',
  hb_corridors_4: 'Wo sich zwei Strecken kreuzen sollen, ohne sich zu treffen, führe eine auf ein Viadukt oder in einen Tunnel: Eine Überwerfung hält beide in Fahrt.',
  hb_planning_title: 'Planung und Baupläne',
  hb_planning_1: 'Im Planungsmodus (J) zeichnest du ganze Projekte, ohne etwas zu bauen: Der Plan zeigt, was er kosten würde.',
  hb_planning_2: 'Wenn du bereit bist, baust du das ganze Projekt oder nur den Teil, der noch passt. Ein Schritt, der nicht mehr passt, wird markiert, damit du ihn ändern kannst.',
  hb_planning_3: 'Baupläne sind wiederverwendbare Anlagen: Speichere einen Teil deines Netzes und setze ihn erneut, gedreht (R) oder gespiegelt (M). Der angezeigte Preis ist der berechnete.',
  hb_planning_4: 'Baupläne lassen sich als Text exportieren und teilen; beim Import wird er zuerst geprüft und baut nie von selbst.',
  hb_eras_title: 'Was sein Alter zeigt',
  hb_eras_1: 'Bahnhöfe, Flughäfen, Häfen, Bahnübergänge, Oberleitungen, Tunnelportale und Bushaltestellen behalten das Aussehen ihres Baujahres.',
  hb_eras_2: 'Eine Renovierung bringt das Aussehen gegen Bezahlung auf den heutigen Stand. Sie ändert nie, was ein Ort leisten kann: Die Kapazität bleibt gleich.',
  hb_eras_3: 'Ein Bahnhof ab 40 Jahren kann unter Denkmalschutz gestellt werden: Er behält sein Aussehen für immer. Konkurrenten renovieren selten, nur ihre wichtigen Bahnhöfe, und behalten manchmal auch einen alten.',
  hb_eras_4: 'Im Winter bleibt Schnee liegen und schmilzt im Frühling; Nächte sind dunkler, mit beleuchteten Fenstern und Lampen.',
  hb_complexes_title: 'Bahnhofskomplexe',
  hb_complexes_1: 'Bahnhöfe und Haltestellen in kurzer Gehweite bilden einen Komplex: Fahrgäste steigen zu Fuß um. Der Bahnhofsinspektor listet sie mit der Gehzeit.',
  hb_complexes_2: 'Ein Ebenenwechsel kostet Zeit: 20 Sekunden pro Ebene über die Treppe. Wo sich Ebenen treffen, kannst du Aufzüge (12 Sekunden) oder Rolltreppen (7 Sekunden) bauen; beide kosten einmalig und etwas Unterhalt im Monat.',
  hb_complexes_3: 'Fahrradstellplätze lassen einen Bahnhof ein Feld weiter in die Straßen reichen; Park & Ride holt Fahrgäste aus Städten, die ein paar Felder weiter weg liegen.',
  hb_complexes_4: 'Schnelleres Umsteigen macht Reisen durch den Komplex attraktiver, so wählen mehr Fahrgäste dein Netz.',
  hb_find_title: 'Dinge finden',
  hb_find_1: 'SUCHEN (Strg+K) findet Städte, Bahnhöfe, Haltestellen, Industrien, Fahrzeuge und Linien sowie die Befehle des Spiels.',
  hb_find_2: 'Es versteht Alltagswörter auf Deutsch und Englisch, kleine Tippfehler und fehlende Umlaute: „Geld“, „traffic jam“, „abreissen“, „bahnof“. Es listet nur: Nichts passiert, bevor du ein Ergebnis wählst.',
  hb_find_3: 'Im Fahrzeugkatalog kannst du beschreiben, was du suchst, etwa „schnelle elektrische Güterlok aus den 60ern“. Die Beschreibung füllt die normalen Filter, als Chips angezeigt; Filter löschen setzt sie zurück. Unbekannte Wörter werden genannt.',
  hb_find_4: 'All das funktioniert offline auf deinem Gerät. Was du eingibst, wird nirgendwohin gesendet.',
  hb_access_title: 'Das Spiel sehen und bedienen',
  hb_access_1: 'Overlays verlassen sich nie nur auf Farbe: Jede Klasse hat ein eigenes Muster (voll, Streifen, Punkte, Rahmen, Karos) und eine Legende in Worten unter der Werkzeugleiste.',
  hb_access_2: 'Lichtsignale zeigen Halt in der oberen Lampe und Fahrt in der unteren; Formsignale zeigen den Flügel waagerecht oder schräg nach oben.',
  hb_access_3: 'Escape schließt eins nach dem anderen: eine Frage, ein Menü, ein Fenster, dann das Werkzeug. Es verlässt auch ein Textfeld.',
  hb_access_4: 'Die Einstellungen bieten hohen Kontrast, weniger Bewegung, eine größere Oberfläche und das Abschalten von Kamerabewegung und Bildschirmwackeln. Fehler sagen, was schiefging und was als Nächstes zu tun ist.',
  find_try: 'Probier Alltagswörter:',
  find_try_words: 'Geld|Stau|Bushaltestelle|U-Bahn|Blaupause|abreißen',
  adv_why: 'Warum?',
  adv_only_suggests: 'Der Berater weist nur auf Dinge hin. Er baut und kauft nie etwas: Du entscheidest.',
  adv_platform_short_why: 'Gemessen über die letzten 15 Minuten: Ein Zug lud mit weniger als 90 % seiner Türen am Bahnsteig, weil er länger als der Bahnsteig ist.',
  adv_add_track_why: 'Bei mehr als einem Viertel der letzten Prüfungen wartete ein Zug auf die Einfahrt, während die Bahnsteige über 55 % der Zeit belegt waren.',
  adv_storage_why: 'Das Lager des Bahnhofs für wartende Fracht ist fast voll; was nicht hineinpasst, geht verloren.',
  adv_turnaround_why: 'In den letzten 15 Minuten mussten hier mehr als drei Züge umsetzen, was an einem Kopfbahnhof Zeit kostet.',
  adv_terminus_why: 'Ein Kopfbahnhof mit einem Gleis, an dem bei über 30 % der letzten Prüfungen ein Zug auf die Einfahrt wartete.',
  adv_passing_loop_why: 'Die Zahl ist die längste Zeit, die Züge zuletzt auf diesem eingleisigen Abschnitt gewartet haben (sie klingt mit der Zeit ab); über 60 Sekunden lohnt sich eine Ausweiche.',
  adv_single_short_why: 'Züge warteten über 60 Sekunden auf diesem Abschnitt, aber er ist kürzer als dein längster Zug plus Platz für Weichen; nur ein zweites Gleis hilft.',
  adv_deadlock_why: 'In den letzten zehn Minuten standen sich diese Züge gegenüber und keiner kam weiter, bis das Spiel sie entwirrt hat.',
  adv_overloaded_why: 'Die Leistung der Loks reicht für das Zuggewicht nicht, deshalb fährt er Steigungen und Anfahrten sehr langsam.',
  adv_line_saturated_why: 'Die Züge der Linie fassen zusammen mehr als das Vierfache der an den Halten wartenden Fahrgäste, nachdem jeder mindestens sechs Fahrten gemacht hat.',
  adv_slow_ahead_why: 'Über 40 Sekunden lang fuhr dieser Zug hinter einem Zug mit weniger als 80 % seiner eigenen Geschwindigkeit.',
  err_no_money_fix: 'Auf Einnahmen warten, ein ungenutztes Fahrzeug verkaufen oder unter Finanzen einen Kredit aufnehmen.',
  err_town_building_fix: 'Um die Häuser herum bauen oder sie mit dem Abrisswerkzeug entfernen, wenn die Stadt es erlaubt.',
  err_industry_fix: 'Die Strecke um die Industrie herumführen.',
  err_no_path_fix: 'Nähere Punkte wählen, Wasser und steile Hänge umgehen oder Brücken und Tunnel erforschen.',
  err_bad_terrain_fix: 'Ebenes Land wählen; Brücken und Tunnel gibt es durch Forschung.',
  err_occupied_fix: 'Ein freies Feld wählen oder dieses mit dem Abrisswerkzeug räumen.',
  err_depot_on_line_fix: 'Das Depot auf ein freies Feld am Ende eines Gleises setzen.',
