  err_station_in_use_fix: 'Warten, bis der Zug abgefahren ist, oder ihn zuerst anhalten.',
  err_depot_in_use_fix: 'Die Züge zuerst herausschicken oder verkaufen.',
  err_level_required_fix: 'Mehr Fracht und Fahrgäste befördern, um die nächste Firmenstufe zu erreichen.',
