  ng_tcost: 'Zwischen Nachbarstädten: {flat}% eben, {slope}% Steigung, {bridge}% Brücken, {tunnel}% Tunnel. Baukosten: {c}',
  tcost_low: 'niedrig',
  tcost_medium: 'mittel',
  tcost_high: 'hoch',
  ng_mega_warn: '192 × 192 ist die größte Karte, etwa neunmal so groß wie die klassische. Der Aufbau der Welt dauert einen Moment, und ältere Handys laufen eventuell langsamer. Gespeichert wird wie gewohnt.',
  terrain_classic: 'Klassisch',
  terrain_classic_desc: 'Die vertraute Tracklands-Welt: Wiesen in der Mitte, eine Westküste, zwei Flüsse, Berge im Norden und Süden.',
  terrain_countryside: 'Sanftes Hügelland',
  terrain_countryside_desc: 'Sanfte Hügel, drei Flüsse, Ackerland um die Städte und kaum Berge. Günstig zu bauen, gut für das erste Spiel.',
  terrain_plains: 'Weite Ebenen',
  terrain_plains_desc: 'Flach, offen und trocken, mit weiten Feldern und vielen kleinen Städten. Lange Geraden; Fracht und Agrargüter dominieren.',
  terrain_highlands: 'Hochland',
  terrain_highlands_desc: 'Welliges Hochland und bewaldete Hügel. Flüsse schneiden Täler, niedrige Pässe verbinden die Regionen; Strecken folgen den Tälern.',
  terrain_alpine: 'Alpin',
  terrain_alpine_desc: 'Hohe Berge, tiefe Täler und wenige Städte. Tunnel und Brücken sind teuer; eine gute Tallinie ist viel wert.',
  terrain_riverlands: 'Flusslandschaft',
  terrain_riverlands_desc: 'Fünf breite Flüsse und ihre Täler. Städte liegen am Wasser; Schiffe lohnen sich, die Bahn braucht Brücken.',
  terrain_lakes: 'Seenland',
  terrain_lakes_desc: 'Viele Seen zwischen Wäldern und Wiesen. Strecken winden sich ums Wasser; Fähren nehmen den kurzen Weg.',
  terrain_coastal: 'Küstenland',
  terrain_coastal_desc: 'Eine lange Küste im Westen und Süden mit Hafenstädten. Häfen und Küstenschifffahrt lohnen sich; die Bahn erschließt das Hinterland.',
  terrain_archipelago: 'Inselwelt',
  terrain_archipelago_desc: 'Jede Region ist eine Insel, auch die Startinsel. Schiffe und lange Brücken verbinden sie; Wachstum kostet mehr.',
  terrain_industrial: 'Industriebecken',
  terrain_industrial_desc: 'Niedriges, offenes Land mit anderthalbmal so vielen Betrieben und mehr Städten. Dichte Güternetze und kurze Wege.',
  terrain_frontier: 'Trockenes Grenzland',
  terrain_frontier_desc: 'Trockene Ebenen, Tafelberge und verstreute Städte. Wenig Wasser und Wald; Minen und Ölfelder liegen auf ihren Lagerstätten.',
  terrain_snowland: 'Nördliches Schneeland',
  terrain_snowland_desc: 'Eine kalte Welt aus Kiefernwäldern, Schneefeldern und gefrorenen Hügeln. Schnee ist häufiger; Holz und Bergbau tragen die Wirtschaft.',
  terrain_continental: 'Kontinental (Mega)',
