  hb_roads_title: 'Straßen, Brücken und Tunnel',
  hb_roads_1: 'Das Straßenwerkzeug baut acht Straßentypen: wähle einen in der Leiste. Jeder hat ein Tempolimit und eine Kapazität (wie viele Autos, bevor es langsamer wird).',
  hb_roads_2: 'Ziehe über einen Fluss (bis 8 Felder) für eine Brücke, gerade durch einen Hügel (bis 12 Felder) für einen Tunnel.',
  hb_roads_3: 'Vierspurige Straßen, Schnellstraßen und Autobahnen überqueren Bahnen auf Brücken statt Bahnübergängen: Züge warten nie auf sie.',
  hb_roads_4: 'Einbahnstraßen werden nur in Zeichenrichtung befahren. Bustrassen sind nur für Busse.',
  hb_roads_5: 'Ein besserer Typ über einer bestehenden Straße wertet sie für den Preisunterschied auf. Rückgängig stellt den alten Typ her.',
  hb_terminals_title: 'Häfen und Flughäfen',
  hb_terminals_1: 'Häfen und Flughäfen gibt es in drei Größen. Baue sie im Inspektor aus: mehr Reichweite, schnellere Abfertigung, die größten Schiffe und Flugzeuge.',
  hb_terminals_2: 'Ein Hafen hat Liegeplätze: weitere Schiffe warten vor dem Kai. Ein Flughafen hat Pistenslots: Flugzeuge warten am Gate oder kreisen.',
  hb_terminals_3: 'Der Inspektor zeigt belegte Liegeplätze und genutzte Pistenslots. Wartende Schiffe oder kreisende Flugzeuge heißen: ausbauen oder Verkehr verteilen.',
  hb_terminals_4: 'Schiffe werden in Häfen mit Kränen gewartet, Flugzeuge an jedem Flughafen, während sie laden.',
  hb_standing_title: 'Ruf, Verträge und Konkurrenz',
  hb_standing_1: 'Dein Ruf ergibt sich aus der Bewertung der bedienten Städte, der Qualität deiner Linien und deiner Vertragsbilanz. Er skaliert die Vertragsprämien.',
  hb_standing_2: 'Manche Verträge haben Fristen: verfallen sie, leidet deine Bilanz und die Stadt. Service-Level-Verträge zählen ganze Monate mit einer Qualität.',
  hb_standing_3: 'Eine Stadt, die dich mag, kann eine Konzession anbieten: drei Monate guter Nahverkehr, und Konkurrenzbusse bleiben ein Jahr draußen.',
  hb_standing_4: 'Konkurrenten betreiben Fernbusse, Stadtbusse oder Lkw und zahlen selbst. Wer drei Monate verschuldet ist, verkauft billig; ab Stufe 8 kannst du jeden kaufen.',
  hb_standing_5: 'Der Tab ANALYSE im Finanzpanel zeigt Gewinn nach Sparte, Linie, Stadt und Fracht, den Geldfluss und was jedes Fahrzeug eingespielt hat.',
  hb_fleetcare_title: 'Flottenpflege',
  hb_fleetcare_1: 'Stelle ein altes Fahrzeug ins Depot oder die Garage und arbeite es auf: der Großteil des Alters verschwindet für etwa ein Drittel des Neupreises.',
  hb_fleetcare_2: 'Fahrzeuge ab 12 Jahren können Museumsfahrten fahren: Freizeit- und Touristenfahrten zahlen viel mehr, Städte ziehen mehr Touristen an.',
  hb_fleetcare_3: 'Züge werden im Depot, Busse in der Garage gewartet; Trams an der ersten Haltestelle ihrer Linie, Schiffe in Häfen mit Kränen, Flugzeuge an Flughäfen.',
  hb_fleetcare_4: 'Ersatzregeln tauschen alte Modelle bei der Wartung gegen neuere.',
  hb_saves_title: 'Spielstände und Backups',
  hb_saves_1: 'Das Spiel speichert selbst (Einstellungen: wie oft). Backups entstehen alle 5 Spielminuten, beim Verlassen zum Titel und vor einem Import.',
  hb_saves_2: 'Einstellungen → Backups listet sie; stelle jedes wieder her, das aktuelle Spiel wird vorher gesichert. Nach einem Fehler gibt es zusätzlich eine Absturz-Sicherung.',
  hb_saves_3: '„Spielstand prüfen“ sucht nach Dingen, die nie vorkommen sollten, und ändert nichts. Kopiere die Diagnose für eine Fehlermeldung; sie enthält keine persönlichen Daten.',
  hb_saves_4: 'Exportiere einen Spielstand als Text oder Datei, um ihn auf ein anderes Gerät zu bringen; alles andere bleibt auf diesem.',
  hb_shortcuts_title: 'Tastenkürzel',
  hb_shortcuts_1: 'Leertaste: Pause · . und , : schneller / langsamer (bis 8×)',
  hb_shortcuts_2: 'F oder Strg+K: alles finden oder einen Befehl tippen (Panel öffnen, Werkzeug wählen, Overlay zeigen)',
  hb_shortcuts_3: '1 Auswahl · 2 Gleis · 3 Bahnhof · 4 Depot · 5 Zugladen · 6 Abriss · 7 Deko · 8 Signal · 9 Wegpunkt',
  hb_shortcuts_4: 'R Straße · B Haltestelle · L Linie · I Industrie · O Overlays · H Verkehrs-Heatmap',
  hb_shortcuts_5: 'T Züge · M Karte · ? Handbuch · Esc schließen oder abbrechen · Enter bauen (Touch-Plan)',
  hb_shortcuts_6: 'W A S D oder Pfeile: Kamera bewegen · Q / E: drehen · + / −: zoomen (mit dem Bahnhofswerkzeug: Gleise)',
  hb_shortcuts_7: 'Strg+Z: letzte Baumaßnahme rückgängig (10 Sekunden)',
  hb_shortcuts_8: 'Im Führerstand: W / S Leistung, X Bremse, Esc verlässt',
