  acc_help: 'Gebäude in Gehweite einer gut bedienten Haltestelle oder eines Bahnhofs sind gut erreichbar. Gute Erreichbarkeit bringt mehr Reisende, höheren Bodenwert, dichtere Bebauung und schnelleres Wachstum – und weniger Autos.',
