  hb_journeys_title: 'Reisen & Umstiege',
  hb_journeys_1: 'Jede Ladung kennt ihre Reise: wo und wann sie begann, wohin sie will und welche Fahrzeuge sie trugen.',
  hb_journeys_2: 'Reisende haben einen Zweck – Pendeln, Einkaufen, Bildung, Freizeit, Tourismus, Geschäft, Fernreise – und fahren zu dem, was andere Orte bieten, wenn die Reise schnell genug ist.',
  hb_journeys_3: 'Sie wählen den besten Weg über alle deine Linien: Bus, Tram, Zug, Fähre und Flugzeug, mit Fußwegen zwischen nahen Haltestellen. Warten, Fahren und jeder Umstieg zählen.',
  hb_journeys_4: 'Fracht findet selbst ihren Weg zu einem Abnehmer: Ein Lkw bringt Kohle zu einem Güterbahnhof, wo ein Zug sie weiterfährt. Du musst keine Ladung selbst leiten.',
  hb_journeys_5: 'Eine Reise wird einmal bei Ankunft bezahlt: Der Erlös für die ganze Strecke wird nach gefahrener Strecke auf alle beteiligten Fahrzeuge verteilt. Umsteigen allein bringt nichts ein.',
  hb_journeys_6: 'Züge ohne Fahrplan (automatisch) nehmen weiterhin alle mit, die auf „irgendeinen Zug“ warten; gib Zügen eine Route, damit sie Teil des Netzes werden.',
  size_192: 'Gigantisch',
  size_192_desc: '192 × 192 Felder: ein ganzes Land, über hundert Städte; für schnelle Geräte',
  airport_size_1: 'Regionalflughafen',
  airport_size_2: 'Internationaler Flughafen',
  airport_stats: 'Einzugsgebiet {r} Felder · Abfertigung {t} %',
  airport_upgrade: 'Zum internationalen Flughafen ausbauen',
  airport_international_desc: 'Längere Piste und größeres Terminal: größeres Einzugsgebiet, 30 % schnellere Abfertigung, nimmt Cargojet und Skyliner 300 an.',
  airport_upgraded: '{name} ist jetzt ein internationaler Flughafen',
  airport_international: 'Internationaler Flughafen',
  err_airport_small: 'Dieses Flugzeug braucht an jedem Halt einen internationalen Flughafen',
  hb_rollingstock_title: 'Loks & Triebzüge',
  hb_rollingstock_1: 'Jede Epoche bietet mehrere Loks für verschiedene Aufgaben: Rangier- und Nahverkehrsloks sind günstig, Fern- und Expressloks schnell, Schwerlast- und Gebirgsloks ziehen mehr bergauf. Spätere Modelle sind nicht in allem besser.',
  hb_rollingstock_2: 'Triebzüge (Diesel-, Elektro-, Hochgeschwindigkeits-Triebzug) befördern Fahrgäste in den Triebköpfen, fahren aus beiden Richtungen, haben einen schnelleren Fahrgastwechsel und behalten ihre Beschleunigung auch voll besetzt. Sie fahren als Einheit mit Mittelwagen und ziehen nie Güterwagen.',
  hb_rollingstock_3: 'Die Zusammenstellung bringt etwas mehr: ein Premiumwagen hebt die Fahrpreise, ein Speisewagen erhöht jedes Fahrgeld des Zuges, Schlafwagen lohnen sich auf langen Reisen. Post- und Paketwagen nehmen die Post mit.',
  hb_rollingstock_4: 'Spezialwagen fassen mehr von einer Ladung (Getreide, Zement, Coils, Chemie) oder viel mehr von vielen (Großraumwagen brauchen Schwerlastverkehr). Doppelstock-Containerwagen sind zu hoch für die Oberleitung: Zieh sie mit Dampf oder Diesel.',
  hb_rollingstock_5: 'Der Fahrzeugkatalog (Menü: Fahrzeuge) zeigt jedes Modell mit Einsatz, Werten, Freischaltung, Stärken und Schwächen. Durchsuche und filtere ihn, markiere Favoriten (sie stehen in den Baukästen zuerst) und vergleiche bis zu vier Modelle nebeneinander.',
  cat_tab_vehicles: 'Fahrzeuge',
