  mu_badge: 'Triebzug',
  mu_badge_desc: 'Befördert selbst Fahrgäste, fährt aus beiden Richtungen, schneller Fahrgastwechsel und volle Beschleunigung auch beladen.',
  special_badge: 'Spezial-Güterverkehr',
  hb_freight_5: 'Neuere Ketten: Stein und Sand ergeben Zement, Ton ergibt Ziegel – Baustoffe, mit denen Städte schneller wachsen. Vieh, Milch, Obst und Fisch werden zu Nahrung; Öl ergibt Chemikalien; Stahl, Chemikalien und Maschinen ergeben Fahrzeuge; Kupfer und Chemikalien ergeben Elektronik. Kraftwerke verbrennen Kohle und Öl.',
  hb_freight_6: 'Jedes passende Fahrzeug kann jede Fracht befördern, aber manche Verkehrsarten zahlen besser: Schüttgut per Bahn und Schiff, Verderbliches per Lkw, Wertvolles per Lkw und Flugzeug. Das Industriefenster zeigt, was sich am meisten lohnt.',
