  hb_cities_title: 'Städte und ihr Charakter',
  hb_cities_1: 'Jede Stadt hat einen Charakter: historisch, Industrie, Pendler, Tourismus, Hafen, Universität, Technologie, Markt, Berg oder Eisenbahn. Du siehst ihn im Stadtfenster.',
  hb_cities_2: 'Der Charakter prägt die Straßen (Raster, Ringe um einen alten Kern, eine lange Straße entlang Küste oder Tal), die Gebäude und ihre Farben und wie hoch die Stadt bauen darf.',
  hb_cities_3: 'Er verändert auch, was die Stadt will: Universitäts- und Pendlerstädte reisen viel, Touristenstädte vor allem im Sommer, Industriestädte brauchen mehr Waren und Maschinen zum Wachsen, Marktstädte weniger Lebensmittel.',
  hb_cities_4: 'Städte errichten beim Wachsen Wahrzeichen: eine Kathedrale, ein Museum, ein Stadion, einen Leuchtturm … Manche sind geschützt und können nie abgerissen werden; die anderen brauchen die Denkmal-Zustimmung des Rats.',
  hb_cities_5: 'Große Städte bekommen ein zweites Zentrum mit hohen Gebäuden, ersetzen niedrige Häuser durch Wohnungen und Büros, und benachbarte Städte bilden einen Ballungsraum mit mehr Verkehr untereinander.',
  arch_historic: 'Historische Stadt',
  arch_historic_desc: 'Ein dichter alter Kern mit Ringstraßen und alter Architektur. Der Rat schützt das Erbe; Land im Zentrum ist teuer.',
  arch_industrial: 'Industriestadt',
  arch_industrial_desc: 'Werke und Lagerhallen am Stadtrand, Backsteinstraßen, breite Blöcke. Fragt Waren, Maschinen und Stahl nach.',
  arch_commuter: 'Pendlerstadt',
  arch_commuter_desc: 'Weite Vororte um ein kompaktes Zentrum; viele Menschen reisen, und die Bahn zieht die Stadt zu ihren Bahnhöfen.',
  arch_tourism: 'Touristenstadt',
  arch_tourism_desc: 'Hotels, Museen und Plätze. Besucher kommen am meisten im Sommer, am wenigsten im Winter.',
  arch_port: 'Hafenstadt',
  arch_port_desc: 'Eine lange Uferzone mit Hafenschuppen; sie wächst entlang der Küste und fragt Treibstoff und Waren nach.',
  arch_university: 'Universitätsstadt',
  arch_university_desc: 'Ein Campus und viele Studierende: viele Fahrgäste und viel Post.',
  arch_tech: 'Technologiestadt',
  arch_tech_desc: 'Glastürme und Büros: hoch, wertvoll und voller Post.',
  arch_market: 'Marktstadt',
  arch_market_desc: 'Ein kleines Zentrum zwischen Höfen; wächst langsam, braucht wenig Lebensmittel von außen, Land ist billig.',
  arch_mountain: 'Bergstadt',
  arch_mountain_desc: 'Chalets entlang eines Tals; das Gelände begrenzt sie, sie bleibt kompakt. Tunnel lohnen sich hier.',
  arch_railway: 'Eisenbahnstadt',
  arch_railway_desc: 'Um die Bahn gewachsen: Bahnhöfe ziehen die Stadt stärker um sich als irgendwo sonst.',
