  town_industries: 'Industrie in der Nähe',
  town_relationship: 'Verhältnis',
  hb_buslines_6: 'Städte haben eigene Autos. Busse und Lkw warten an Kreuzungen und roten Ampeln und fahren auf vollen Straßen langsamer. Eine Busspur (Straßenwerkzeug, nach der Forschung Busspuren; Großstädte müssen zustimmen) lässt Busse am Verkehr vorbeifahren, und Busvorrang schaltet die Ampeln für sie früher auf Grün.',
  road_mode_lane: 'Busspur',
  hint_lane: 'Entlang einer Straße ziehen: Busse und Reisebusse auf einer Busspur fahren an den Autos der Stadt vorbei und stehen nicht im Stau.',
  hint_drag_lane: 'Entlang einer vorhandenen Straße ziehen, um eine Busspur zu markieren',
