  rv_replaced: '{name} ist jetzt ein {m}',
  tm_transport: 'Nahverkehr',
  tm_districts: 'Viertel',
  tm_authority: 'Verwaltung',
  tm_coverage: 'In Gehweite einer Haltestelle',
  tm_town_none: 'Noch kein Nahverkehr: Baue hier eine Bushaltestelle oder einen Bahnhof.',
  tm_town_gap: 'Der {area} ({n} % der Stadt) hat keinen Halt in Reichweite.',
  hb_buslines_title: 'Buslinien und Haltestellen',
  hb_buslines_1: 'Das Linien-Werkzeug (L) plant eine Linie: Tippe oder klicke die Halte der Reihe nach an, wähle ein Muster (Ring, hin und zurück, Einbahn, Pendel) und ein Busmodell, dann Erstellen. Die Schätzung zeigt Fahrzeit, Takt und eine sinnvolle Busanzahl.',
  hb_buslines_2: 'Fahrgäste wählen ihr Ziel. Ein dichter Takt verkürzt die Wartezeit; eine Linie mit zu wenigen Bussen wird voll, eine mit zu vielen fährt leer. Die automatische Zuteilung kauft und verkauft Busse passend zur Nachfrage.',
  hb_buslines_3: 'Baue belebte Halte aus: Stadthaltestelle, Busbucht, Busbahnhof, Terminal, Umsteigeknoten. Größere Halte bedienen mehr Busse gleichzeitig, fertigen schneller ab, reichen weiter und erleichtern das Umsteigen zum Zug. Extras wie Wartehäuschen oder eine Umsteigehalle bringen Komfort und Kapazität.',
  hb_buslines_4: 'Ein Halt nahe einem Bahnhof ist ein Zubringer: Fahrgäste fahren mit dem Bus zum Zug, und ankommende Bahnreisende nehmen den Bus für die letzte Meile.',
  hb_buslines_5: 'Busse altern und werden unzuverlässiger. Ein Busdepot wartet sie, stellt sie ab und verkauft neue; eine Ersetzungsregel erneuert ein Modell automatisch, wenn seine Busse alt werden.',
  hb_overview_title: 'Verkehr-Fenster und Berater',
  hb_overview_1: 'Das Verkehr-Fenster zeigt alle Verkehrsarten an einem Ort: Fahrzeuge, Linien, Geld sowie Fahrgäste oder Fracht für Bahn, Bus, Tram, Lkw, Schiff und Flug.',
  hb_overview_2: 'Linien zeigt jede Linie mit Takt, Fahrgästen, Fracht, Gewinn, Verspätung und Kapazität. Fahrzeuge listet alles, was dir gehört; filtere nach Art, Linie, Stadt oder Status und wähle mehrere aus, um sie gemeinsam zu steuern.',
  hb_overview_3: 'Probleme sammelt, was der Berater gefunden hat: volle oder leere Linien, volle Bahnhöfe und Halte, Staus, Fahrzeuge ohne Route, Städte ohne Nahverkehr. Viele Hinweise haben einen Knopf, der sie behebt.',
  hb_overview_4: 'Der Berater unterbricht dich nie. Dringende Hinweise erscheinen nur als Zahl am Verkehr-Knopf.',
