  hb_tycoon_title: 'Die Firma führen',
  hb_tycoon_1: 'Jede Münze wird im Finanz-Panel gebucht: Einnahmen und Kosten nach Kategorie, je Zug, Bahnhof und Fahrzeug, Monat für Monat. Tippe eine Protokollzeile, um ihr Objekt zu sehen.',
  hb_tycoon_2: 'Ein Kredit bringt jetzt Geld gegen monatliche Zinsen. Der Firmenwert ist Kasse minus Schulden plus Züge, Gleise, Bahnhöfe, Industrieanteile und jüngste Gewinne.',
  hb_tycoon_3: 'Jede Stadt bewertet die Firma. Guter Service hebt die Bewertung; Abriss, Rodung und Lärm senken sie. Manche Genehmigungen brauchen eine gute Bewertung.',
  hb_tycoon_4: 'Kaufe Anteile an Industrien für monatliche Dividenden; ab 50 % führst du den Betrieb (+10 % Produktion). Fördere Ausbauten oder neue Betriebe mit dem Industrie-Werkzeug.',
  hb_tycoon_5: 'Konkurrierende Busfirmen werben um die Fahrgäste der Städte: der Halt mit der besseren Frachtbewertung bekommt mehr. Das Firmen-Panel zeigt die Rangliste.',
  hb_transport_title: 'Straße, Wasser und Luft',
  hb_transport_1: 'Baue Straßen mit dem Straßen-Werkzeug und setze Bus- und Lkw-Halte darauf. Gib jedem Fahrzeug zwei oder mehr Halte; es verdient wie ein Zug.',
  hb_transport_2: 'Verlege Tramgleis entlang der Straßen (Straßen-Werkzeug, Tramgleis), dann Tramhalte. Straßenbahnen befördern auch innerhalb ihrer Stadt.',
  hb_transport_3: 'Häfen stehen am Ufer; Schiffe fahren zwischen Häfen auf demselben Wasser. Fähren bringen Fahrgäste, Frachter und Tanker Güter.',
  hb_transport_4: 'Flughäfen brauchen eine ebene 3×3-Fläche. Flugzeuge sind schnell, aber teuer: lange Strecken zwischen großen Städten lohnen sich am meisten.',
  hb_transport_5: 'Ein Halt, Hafen oder Flughafen in Reichweite eines Bahnhofs übergibt Fahrgäste und Güter an die Züge und wird für seinen Abschnitt bezahlt.',
  hb_world_title: 'Welt, Nachrichten und Ziele',
  hb_world_1: 'Die Jahreszeiten folgen dem Kalender. Sturm, Nebel und Schnee bremsen Fahrzeuge; im Winter liegt Schnee; Farmen produzieren je nach Jahreszeit. Der Wetter-Chip oben erklärt das Wetter.',
  hb_world_2: 'Die Zeitung berichtet: wachsende Städte und Industrien, Marktereignisse, die Konjunktur und die Konkurrenz. Tippe eine Meldung, um sie zu sehen.',
  hb_world_3: 'Boom und Flaute ändern den Erlös jeder Lieferung um 12 %. Baue in der Flaute, verdiene im Boom.',
  hb_world_4: 'Listen finden jede Stadt, Industrie und jeden Bahnhof nach Namen. Neue Spiele können größer sein (96 oder 128 Felder) oder aus einer eigenen Höhenkarte entstehen.',
  hb_world_5: 'Szenarien setzen Ziele und eine Frist; der Editor macht eigene und teilt sie als Text. Fahre einen Zug selbst mit „Fahren“ in seinem Panel.',
  ov_trackcheck: 'Gleisprüfung', ov_trackcheck_desc: 'Rot: fehlerhafte Verbindungen · gelb: Gleisenden im Winkel · grau: offene Gleisenden',
  ng_rivals: 'Konkurrenzfirmen', rivals: 'Konkurrenz', rival_you: 'du', rival_owned: 'Eine Konkurrenzfirma betreibt das. Du kannst es nicht ändern.', rival_stats: '{b} Busse · {s} Halte · letzter Monat {p} ●', rivals_help: 'Konkurrierende Busfirmen eröffnen Linien zwischen Städten. Ihre Halte teilen sich die Fahrgäste jeder Stadt mit deinen nach Frachtbewertung: bediene die Städte gut, um sie zu halten.', err_rival_stop: 'Das gehört einer Konkurrenzfirma', news_rival_line: '{rival} eröffnet eine Buslinie {a} – {b}',
