  hq_help: 'Ein 2×2-Bürogebäude auf freiem Land. Die Stadt, in der es steht, mag das: +8 Verhältnis beim Bau und jeden Monat etwas mehr. Beim Umzug wird der alte für die Hälfte verkauft.',
