  stop_help_dock: 'Schiffe fahren auf Wasser, das beide Häfen verbindet. Die Fähre bringt Fahrgäste und Post, der Küstenfrachter Güter, der Tanker Flüssiges. Ein Bahnhof im Umkreis von 3 Feldern übernimmt Umsteiger.',
