  st_timetable: 'Wartet auf Abfahrtszeit in {station} · {s} s',
  tab_trains: 'Züge', tab_lines: 'Linien', tab_fleet: 'Flotte',
  tt_spacing: 'Takt', tt_off: 'Aus', tt_even: 'Gleichmäßig (auto)', tt_every: 'Alle {n} min', tt_active: 'Fährt am ersten Halt alle ~{n} min ab', tt_learning: 'Umlaufzeit wird gemessen…',
  tt_help: 'Züge mit denselben Halten bilden eine Linie. Mit Takt fahren sie am ersten Halt gleichmäßig verteilt ab: kürzere Wartezeiten, keine Pulks.',
  lines_empty: 'Noch keine Linien. Gib Zügen eine manuelle Route: Züge mit denselben Halten bilden eine Linie.', line_trains: '{n} Züge', line_trains_1: 'Ein Zug', line_add_train: 'Zug hinzufügen',
  fleet_replace: 'Ersetzen durch', fleet_replace_btn: 'Alle ersetzen', fleet_confirm: 'Die {from}-Loks von {n} Zügen durch {to} ersetzen? Wagen bleiben; alte Loks werden zu 50 % verkauft.', fleet_done: '{n} Züge modernisiert, {m} unverändert',
