  group: 'Gruppe', group_none: 'Keine Gruppe', group_new: 'Neue Gruppe…', group_prompt: 'Name der Gruppe', group_other: 'Weitere Züge',
  map_geo: 'Gelände', map_schematic: 'Netzplan', netmap: 'Netzplan', netmap_empty: 'Linien erscheinen hier, sobald Züge manuelle Routen fahren.',
  all: 'Alle',
  handbook: 'Handbuch', menu_handbook: 'Handbuch', menu_settings: 'Einstellungen', hb_tutorial_note: 'Die geführte Einführung noch einmal?',
  hb_start_title: 'Erste Schritte',
  hb_start_1: 'Baue einen Bahnhof neben einer Stadt oder Industrie: Die markierte Fläche zeigt, was er versorgt.',
  hb_start_2: 'Verbinde zwei Bahnhöfe mit Gleisen (ziehen) und setze ein Depot neben die Strecke.',
  hb_start_3: 'Kaufe im Depot einen Zug. Mit automatischer Route findet er Fracht und Fahrgäste selbst.',
  hb_start_4: 'Lange Fahrten bringen mehr. Städte, die bekommen, was sie brauchen, wachsen – und mit ihnen der Verkehr.',
  hb_stations_title: 'Bahnhöfe & Bahnsteige',
  hb_stations_1: 'Baue einen Bahnhof, indem du entlang des Gleises ziehst: Die Vorschau zeigt Bahnsteiglänge, was hineinpasst und den Preis. Die Anzahl der Gleise stellst du in der Leiste über der Werkzeugleiste ein. Vom Bahnsteigende nach außen ziehen verlängert ihn. Lange Züge nutzen auch kurze Bahnsteige, sie laden dort nur langsamer.',
  hb_stations_2: 'Gib vollen Bahnhöfen weitere Gleise. Jedes Gleis lässt sich für Personen-, Güter-, Express- oder Durchgangszüge reservieren.',
  hb_stations_3: 'Ein Durchgangsgleis bleibt für Züge ohne Halt frei: Dort können schnellere Züge überholen.',
  hb_stations_4: 'Bahnhöfe ändern ihr Aussehen mit Stufe und Nutzung: Haltepunkt, Dorf-, Stadt-, Großstadt-, Hauptbahnhof, Grand Terminal, Güterbahnhof.',
  hb_signals_title: 'Signale',
  hb_signals_1: 'Die Bahn sichert sich selbst: Züge reservieren die Strecke vor sich und stoßen nie zusammen. Signale dienen der Feinabstimmung.',
  hb_signals_2: 'Blocksignal: Ein Zug fährt erst ein, wenn der ganze Abschnitt dahinter frei ist. Pfadsignal: hält Weichen frei.',
  hb_signals_3: 'Einrichtungssignale machen aus zweigleisigen Strecken Richtungsgleise. Ziehe das Signalwerkzeug entlang einer Strecke für eine ganze Reihe.',
  hb_signals_4: 'Die Ansicht „Blöcke“ färbt jeden Signalabschnitt ein – so siehst du, wo Züge warten werden.',
  hb_single_title: 'Eingleisig & Ausweichen',
  hb_single_1: 'Eingleisige Strecken sind günstiger, aber Gegenzüge müssen aufeinander warten.',
  hb_single_2: 'Ein Ausweichgleis (ein kurzes zweigleisiges Stück) lässt sie kreuzen. Mach es mindestens so lang wie deinen längsten Zug.',
  hb_single_3: 'Der Berater meldet stark befahrene eingleisige Strecken und zeigt, wo ein Ausweichgleis passt.',
  hb_passengers_title: 'Fahrgäste & Umstiege',
  hb_passengers_1: 'Fahrgäste in Zügen mit manueller Route wählen ein Ziel unter den kommenden Halten – große Städte zuerst.',
  hb_passengers_2: 'Wo sich zwei Linien einen Bahnhof teilen, steigen Fahrgäste um. Jede Teilstrecke wird nach ihrer Länge bezahlt.',
  hb_passengers_3: 'Häufige Züge und viele Verbindungen bringen mehr Menschen zum Reisen.',
  hb_passengers_4: 'Das Bahnhofsfenster zeigt, wer wohin will, und alles, was von dort erreichbar ist.',
  hb_lines_title: 'Linien & Takt',
  hb_lines_1: 'Züge mit denselben Halten bilden eine Linie. Der Reiter „Linien“ zeigt jede Linie mit Zügen und Einnahmen.',
  hb_lines_2: 'Mit einem Takt verlassen die Züge den ersten Halt gleichmäßig verteilt: keine Pulks, kürzere Wartezeiten.',
  hb_lines_3: '„Gleichmäßig“ misst die Umlaufzeit und teilt sie durch die Zahl der Züge auf der Linie.',
  hb_lines_4: 'Im Kartenfenster gibt es einen Netzplan mit all deinen Linien.',
  hb_overtaking_title: 'Überholen',
  hb_overtaking_1: 'Ein haltender Zug lässt einen schnelleren vor, wenn dieser auf einem anderen Gleis durch den Bahnhof fährt.',
  hb_overtaking_2: 'Gib vollen Bahnhöfen ein zweites Gleis (am besten als „Durchfahrt“) und Bahnsteige, die ein Feld länger als deine Züge sind.',
  hb_overtaking_3: 'Der Berater zeigt Züge, die ständig langsamere einholen.',
  hb_freight_title: 'Fracht & Produktionsketten',
  hb_freight_1: 'Rohstoffe (Holz, Getreide, Erz, Kohle …) gehen an verarbeitende Industrien, die Waren für Städte herstellen.',
  hb_freight_2: 'Das Industriefenster zeigt, wohin die Produkte gehen können, wie weit und ungefähr, was sie bringen.',
  hb_freight_3: '„Transportiert“ zeigt, wie viel der Produktion deine Züge abholen. Versorgte Industrien wachsen.',
  hb_freight_4: 'Spezialwagen fassen mehr und können einen Bonus bringen; Forschung schaltet sie frei.',
  hb_economy_title: 'Geld & Wachstum',
  hb_economy_1: 'Einnahmen hängen von Frachtwert und Entfernung ab. Züge kosten jede Minute ein wenig Betrieb.',
  hb_economy_2: 'Eine Linie hat nur begrenzt Fahrgäste: Fahren Züge halb leer, binde lieber weitere Städte an, statt Züge hinzuzufügen.',
